"""Apply the source owner's original Debian installation manifests."""
import argparse
import gzip
import json
import os
from pathlib import Path
import shutil
import subprocess
import tempfile


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    for name in ['data', 'source', 'tar', 'install', 'fixperms', 'installdeb', 'output_data', 'output_substvars', 'receipt']:
        parser.add_argument('--' + name.replace('_', '-'), type=Path, required=True)
    parser.add_argument('--makeshlibs', type=Path)
    parser.add_argument('--package', required=True)
    parser.add_argument('--architecture', required=True)
    parser.add_argument('--control-output', action='append', default=[])
    args = parser.parse_args()
    paths = {name: getattr(args, name).absolute() for name in ['data', 'source', 'tar', 'install', 'fixperms', 'installdeb', 'output_data', 'output_substvars', 'receipt']}
    controls = {name: Path(value).absolute() for name, value in (item.split('=', 1) for item in args.control_output)}
    makeshlibs = args.makeshlibs.absolute() if args.makeshlibs else None
    env = dict(os.environ, DEB_HOST_ARCH=args.architecture, LANG='C', LC_ALL='C')
    with tempfile.TemporaryDirectory(prefix='common-debian-install-') as directory:
        work = Path(directory)
        debian, staging = work / 'debian', work / 'staging'
        debian.mkdir(); staging.mkdir()
        for name in ['control', 'changelog', 'compat', args.package + '.install', args.package + '.dirs']:
            shutil.copyfile(paths['source'] / name, debian / name)
        if args.package == 'libswsscommon':
            shutil.copyfile(paths['source'] / 'conffiles', debian / 'conffiles')
        def run(command):
            subprocess.run([str(value) for value in command], cwd=work, env=env, check=True)
        run([paths['tar'], '-xf', paths['data'], '-C', staging])
        run([paths['install'], '-p' + args.package, '--sourcedir=' + str(staging)])
        package = debian / args.package
        doc = package / 'usr/share/doc' / args.package
        doc.mkdir(parents=True)
        (doc / 'changelog.gz').write_bytes(gzip.compress((debian / 'changelog').read_bytes(), mtime=0))
        # Match Make's standard dh sequence instead of preserving the checkout
        # umask on configuration, documentation and newly created directories.
        subprocess.run([str(paths['fixperms']), '-p' + args.package], cwd=work,
                       env=dict(env, DEB_RULES_REQUIRES_ROOT='no'), check=True)
        if makeshlibs:
            run([makeshlibs, '-p' + args.package])
        run([paths['installdeb'], '-p' + args.package])
        produced = package / 'DEBIAN'
        names = {p.name for p in produced.iterdir()} if produced.exists() else set()
        if names != set(controls):
            raise ValueError('unexpected Debian helper outputs: ' + repr(names) + '; expected ' + repr(set(controls)))
        for name, output in controls.items():
            shutil.copyfile(produced / name, output)
        if produced.exists(): shutil.rmtree(produced)
        substvars = debian / (args.package + '.substvars')
        paths['output_substvars'].write_bytes(substvars.read_bytes() if substvars.exists() else b'')
        files = [package] + sorted(package.rglob('*'))
        for path in files:
            os.utime(path, (0, 0), follow_symlinks=False)
        members = work / 'members.txt'
        members.write_text(''.join(str(path.relative_to(package)) + '\n' for path in files))
        run([paths['tar'], '--create', '--format=gnutar', '--uid=0', '--gid=0', '--numeric-owner', '--no-recursion', '--file', paths['output_data'], '-C', package, '-T', members])
        paths['receipt'].write_text(json.dumps({
            '_generated': 'AUTO-GENERATED by debian/stage.py. DO NOT EDIT MANUALLY.',
            'package': args.package, 'architecture': args.architecture,
            'manifest': (debian / (args.package + '.install')).read_text(),
            'control_files': sorted(controls), 'status': 'passed',
        }, indent=2) + '\n')


if __name__ == '__main__':
    main()
